import type React from "react";
import { Accept, FileRejection } from "react-dropzone";

type FileEntryMeta = {
  ext?: string;
  size?: string;
  [key: string]: unknown;
};

export type FileEntry = {
  id: string;
  /** The Native browser file object */
  file: File;
  /** The current status of the file entry */
  status: "idle" | "uploading" | "done" | "error";
  /** 1 - 100 */
  progress: number;
  /** The error message if status  === "error" */
  error?: string;
  /** The File URL if status === "done" */
  url?: string;
  /** The File Meta data */
  meta?: FileEntryMeta;
};

export type FileUploadConfig = {
  /** Accepted MIME types e.g. ["image/*", "application/pdf"] */
  accept?: Accept;
  /** Max file size in bytes */
  maxSize?: number;
  /** Max number of files */
  maxFiles?: number;
  /** Allow selecting multiple files at once */
  multiple?: boolean;
  /** Dropzone title */
  title?: string;
  /** Dropzone description shows on the dropzone */
  description?: string;
  /** Dropzone icon shows on the dropzone */
  icon?: React.ReactNode;
  /** Upload file automaticaly */
  auto?: boolean;
  /** Upload file automaticaly */
  initialFiles?: FileEntry[];
};

export type FileUploadContextValue = {
  files: FileEntry[];
  isDragging: boolean;
  isUploading: boolean;
  isFull: boolean;

  config: FileUploadConfig;

  setIsDragging: (v: boolean) => void;
  addFiles: (files: File[]) => void;
  removeFile: (id: string) => void;
  uploadFile: (id: string) => void;
  uploadAll: () => void;
  removeAll: () => void;
  cancelFile: (id: string) => void;
  retryFile: (id: string) => void;
  onAddRejected?: (fileRejections: FileRejection[]) => void;
};

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import type React from "react";
import type {
  FileEntry,
  FileUploadConfig,
  FileUploadContextValue,
} from "./types";
import { formatBytes, getFileExt } from "./file-upload-utils";
import { FileRejection } from "react-dropzone";

const FileUploadContext = createContext<FileUploadContextValue | undefined>(
  undefined,
);

export type FileUploadProviderProps = {
  children?: React.ReactNode;
  config?: FileUploadConfig;
  /**
   * The actual upload function — provided by the consumer.
   * Must return { url, meta } on success.
   * Throw an error to trigger the error state.
   *
   * @example
   * onUpload={async (file, onProgress) => {
   *   const formData = new FormData();
   *   formData.append("file", file);
   *   const res = await fetch("/api/upload", { method: "POST", body: formData });
   *   const { url } = await res.json();
   *   return { url };
   * }}
   */
  onUpload: (
    file: File,
    onProgress: (pct: number) => void,
  ) => Promise<{ url: string; meta?: Record<string, unknown> }>;
  onComplete?: (files: FileEntry[]) => void;
  onError?: (id: string, error: string) => void;
  onFilesChange?: (files: FileEntry[]) => void;
};

export function useFileUpload(): FileUploadContextValue {
  const ctx = useContext(FileUploadContext);
  if (!ctx) {
    throw new Error("useFileUpload must be used within <FileUploadProvider>");
  }
  return ctx;
}

export function FileUploadProvider({
  children,
  config = { multiple: true, maxSize: 2 * 1024 * 1024 },
  onUpload,
  onComplete,
  onError,
  onFilesChange,
}: FileUploadProviderProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [files, setFiles] = useState<FileEntry[]>(config?.initialFiles ?? []);
  const isFull = config.maxFiles ? files.length >= config.maxFiles : false;

  const abortControllers = useRef<Map<string, AbortController>>(new Map());

  const addFiles = useCallback(
    (incoming: File[]) => {
      setFiles((prev) => {
        const remainingSlots = config.maxFiles
          ? config.maxFiles - prev.length
          : incoming.length;
        if (remainingSlots <= 0) return prev;

        const allowedFiles = incoming.slice(0, remainingSlots);
        const entries: FileEntry[] = allowedFiles.map((file) => ({
          id: crypto.randomUUID(),
          file,
          status: "idle",
          progress: 0,
          meta: {
            ext: getFileExt(file),
            size: formatBytes(file.size),
          },
        }));
        return [...prev, ...entries];
      });
    },
    [config.maxFiles],
  );

  const removeFile = useCallback((id: string) => {
    abortControllers.current.get(id)?.abort();
    abortControllers.current.delete(id);
    setFiles((prev) => prev.filter((f) => f.id !== id));
  }, []);

  const uploadFile = useCallback(
    async (id: string) => {
      setFiles((prev) => {
        const exists = prev.find((f) => f.id === id);
        if (!exists) return prev;
        return prev.map((f) =>
          f.id === id ? { ...f, status: "uploading", progress: 0 } : f,
        );
      });

      let fileEntry = files.find((f) => f.id === id);
      if (!fileEntry) return;
      const targetFile = fileEntry.file;

      setIsUploading(true);

      const onProgress = (pct: number) => {
        setFiles((prev) =>
          prev.map((f) => {
            if (f.id !== id) return f;
            if (Math.abs(f.progress - pct) < 2) return f;
            return { ...f, progress: pct };
          }),
        );
      };

      try {
        const result = await onUpload(targetFile, onProgress);
        let allDone = false;
        setFiles((prev) => {
          const updated = prev.map((f) =>
            f.id === id
              ? { ...f, status: "done" as const, progress: 100, ...result }
              : f,
          );
          allDone = updated.every((f) => f.status === "done");
          if (allDone) {
            queueMicrotask(() => onComplete?.(files));
          }
          return updated;
        });
      } catch (err: unknown) {
        const message =
          err instanceof Error
            ? err.message
            : `Failed to upload ${targetFile.name}`;

        setFiles((prev) =>
          prev.map((f) =>
            f.id === id
              ? { ...f, status: "error" as const, error: message }
              : f,
          ),
        );
        onError?.(id, message);
      } finally {
        abortControllers.current.delete(id);
        setFiles((prev) => {
          const stillUploading = prev.some((f) => f.status === "uploading");
          if (!stillUploading) setIsUploading(false);
          return prev;
        });
      }
    },
    [files, onUpload, onComplete, onError],
  );

  const uploadAll = useCallback(async () => {
    const idleIds = files.filter((f) => f.status === "idle").map((f) => f.id);
    Promise.all(idleIds.map((id) => uploadFile(id)));
  }, [files, uploadFile]);

  const removeAll = useCallback(() => {
    const idsToRemove = files.map((f) => f.id).reverse();

    idsToRemove.forEach((id, index) => {
      setTimeout(() => {
        removeFile(id);
      }, index * 150);
    });
  }, [files, removeFile]);

  const cancelFile = useCallback((id: string) => {
    abortControllers.current.get(id)?.abort();
    abortControllers.current.delete(id);
    setFiles((prev) =>
      prev.map((f) =>
        f.id === id && f.status === "uploading"
          ? { ...f, status: "idle", progress: 0 }
          : f,
      ),
    );
  }, []);

  useEffect(() => {
    if (config.auto) {
      const idleFiles = files.filter((f) => f.status === "idle");
      if (idleFiles.length > 0) {
        idleFiles.forEach((f) => uploadFile(f.id));
      }
    }
  }, [files, config.auto, uploadFile]);

  const retryFile = useCallback(
    async (id: string) => {
      setFiles((prev) =>
        prev.map((f) =>
          f.id === id && f.status === "error"
            ? { ...f, status: "idle", progress: 0, error: undefined }
            : f,
        ),
      );
      await uploadFile(id);
    },
    [uploadFile],
  );

  const onAddRejected = useCallback(
    (fileRejections: FileRejection[]) => {
      fileRejections.forEach(({ file, errors }) => {
        const message = errors.map((e) => e.message).join(", ");
        const fakeEntry: FileEntry = {
          id: crypto.randomUUID(),
          file,
          status: "error",
          progress: 0,
          error: message,
          meta: {
            ext: getFileExt(file),
            size: formatBytes(file.size),
          },
        };
        onError?.(fakeEntry.id, message);
      });
    },
    [onError],
  );

  useEffect(() => {
    onFilesChange?.(files);
  }, [files, onFilesChange]);

  return (
    <FileUploadContext.Provider
      value={{
        removeAll,
        isDragging,
        files,
        isUploading,
        isFull,
        config,
        setIsDragging,
        addFiles,
        removeFile,
        uploadFile,
        uploadAll,
        cancelFile,
        retryFile,
        onAddRejected,
      }}
    >
      {children}
    </FileUploadContext.Provider>
  );
}

import Dropzone, { DropzoneState } from "react-dropzone";
import { useFileUpload } from "./file-upload-context";
import { IconUpload } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

interface FileUploadDropzoneProps {
  className?: string;
  /**
   * Provide a custom render function to override the default UI.
   * Receives the full dropzone state (getRootProps, getInputProps, isDragActive, etc.)
   */
  children?: React.ReactNode | ((state: DropzoneState) => React.ReactNode);
}

export function FileUploadDropzone({
  className,
  children,
}: FileUploadDropzoneProps) {
  const { isDragging, setIsDragging, addFiles, config, files, onAddRejected } =
    useFileUpload();
  const {
    accept,
    multiple,
    maxFiles,
    maxSize,
    title = "Drop your files here",
    description = "Drag and drop files here, or click to browse",
    icon,
  } = config;
  const uploadMax = maxFiles ? Math.max(0, maxFiles - files.length) : undefined;
  return (
    <Dropzone
      accept={accept}
      multiple={multiple}
      maxFiles={uploadMax}
      maxSize={maxSize}
      onDragEnter={() => setIsDragging(true)}
      onDragLeave={() => setIsDragging(false)}
      onDropAccepted={(f) => {
        setIsDragging(false);
        addFiles(f);
      }}
      onDropRejected={(fileRejections) => {
        onAddRejected?.(fileRejections);
        setIsDragging(false);
      }}
    >
      {(dropzoneState) => {
        if (typeof children === "function") {
          return children(dropzoneState) as React.ReactElement;
        }

        if (children) {
          return children as React.ReactElement;
        }

        const { getRootProps, getInputProps } = dropzoneState;

        return (
          <div
            {...getRootProps()}
            className={cn(
              "w-full rounded-2xl border-2 border-dashed cursor-pointer",
              "flex flex-col items-center justify-center gap-4 p-6",
              "bg-muted/20 hover:bg-muted/28 transition-colors duration-150",
              "text-center select-none",
              isDragging
                ? "bg-primary/8 border-primary/70"
                : "border-border/60 hover:border-border",
              className,
            )}
          >
            <input {...getInputProps()} />

            <div
              className={cn(
                "w-20 h-20 rounded-full flex items-center justify-center",
                "bg-primary/3 border border-primary/5",
              )}
            >
              {icon ?? <IconUpload size={32} className="stroke-primary" />}
            </div>

            <div>
              <span className="font-medium text-foreground">{title}</span>
              <p className="text-xs text-muted-foreground max-w-xs leading-relaxed">
                {description}
              </p>
            </div>
          </div>
        );
      }}
    </Dropzone>
  );
}

import { cn } from "@/lib/utils";
import type { FileEntry } from "./types";
import { motion } from "motion/react";
import {
  IconCheck,
  IconFile,
  IconFileTypePdf,
  IconFileTypeXls,
  IconLoader2,
  IconPhoto,
  IconX,
  IconAlertCircle,
  IconRefresh,
  IconVideo,
} from "@tabler/icons-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { formatBytes, formatTimeLeft, getFileExt } from "./file-upload-utils";

function ProgressBar({
  progress,
  status,
}: Pick<FileEntry, "progress" | "status">) {
  return (
    <div className="w-full space-y-1">
      <div className="overflow-hidden rounded-full h-1 bg-muted-foreground/10 w-full">
        <motion.div
          className={cn(
            "h-full rounded-full",
            status === "done"
              ? "bg-green-500 dark:bg-green-400"
              : status === "error"
                ? "bg-red-500"
                : "bg-primary",
          )}
          initial={{ width: "0%" }}
          animate={{ width: `${progress}%` }}
          transition={{ duration: 0.35, ease: "easeOut" }}
        />
      </div>
    </div>
  );
}

function FileTypeIcon({ file, size = 22 }: { file: File; size?: number }) {
  const type = file.type;
  const stroke = 1.8;
  if (type.startsWith("video/"))
    return (
      <IconVideo size={size} strokeWidth={stroke} className="stroke-primary" />
    );
  if (type.startsWith("image/"))
    return (
      <IconPhoto size={size} strokeWidth={stroke} className="stroke-primary" />
    );
  if (type === "application/pdf")
    return (
      <IconFileTypePdf
        size={size}
        strokeWidth={stroke}
        className="stroke-primary"
      />
    );
  if (
    type.includes("spreadsheet") ||
    type.includes("excel") ||
    file.name.endsWith(".xlsx")
  )
    return (
      <IconFileTypeXls
        size={size}
        strokeWidth={stroke}
        className="stroke-primary"
      />
    );
  return (
    <IconFile size={size} strokeWidth={stroke} className="stroke-primary" />
  );
}

function StatusIndicator({ status }: Pick<FileEntry, "status">) {
  if (status === "done") {
    return (
      <div className="w-5 h-5 rounded-full bg-green-500/15 flex items-center justify-center shrink-0">
        <IconCheck
          size={11}
          strokeWidth={2.5}
          className="dark:text-green-400 text-green-500"
        />
      </div>
    );
  }
  if (status === "error") {
    return (
      <div className="w-5 h-5 rounded-full bg-red-500/15 flex items-center justify-center shrink-0">
        <IconAlertCircle size={11} strokeWidth={2.5} className="text-red-500" />
      </div>
    );
  }
  if (status === "uploading") {
    return (
      <IconLoader2 size={12} className="animate-spin text-primary shrink-0" />
    );
  }
  return null;
}

export interface FileUploadItemProps extends FileEntry {
  /** Show as a list row instead of a grid card */
  isList?: boolean;
  onRemove?: (id: string) => void;
  onRetry?: (id: string) => void;
  onCancel?: (id: string) => void;
}

export function FileUploadItem({
  id,
  file,
  status,
  progress,
  error,
  meta,
  url,
  isList = false,
  onRemove,
  onRetry,
  onCancel,
}: FileUploadItemProps) {
  const timeLeft =
    status === "uploading"
      ? formatTimeLeft(progress)
      : status === "error"
        ? "Error"
        : status === "done"
          ? "Done"
          : "";
  const hasError = status === "error" && !!error;
  const name = file.name.replace(/\.[^/.]+$/, "");
  if (isList) {
    return (
      <motion.div
        layout
        initial={{ opacity: 0, y: 8 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -8 }}
        transition={{ duration: 0.2 }}
        className="flex flex-col gap-2.5 rounded-xl border border-border/60 bg-muted/20 px-4 py-3.5 shadow-sm"
      >
        <div className="flex items-center gap-3">
          <div
            className={cn(
              "w-11 h-11 rounded-lg bg-primary/10 flex items-center justify-center ",
              status === "error" && "bg-red-500/10",
            )}
          >
            {status === "error" ? (
              onRetry && (
                <button
                  onClick={() => onRetry(id)}
                  type="button"
                  className="text-[10px] text-red-500 hover:text-red-400 flex items-center gap-1 text-xl cursor-pointer"
                >
                  <IconRefresh size={24} strokeWidth={2} />
                </button>
              )
            ) : (
              <FileTypeIcon file={file} size={22} />
            )}
          </div>

          <div className="flex-1 min-w-0">
            <p className="text-sm font-semibold truncate text-foreground leading-tight">
              {name}
            </p>
            <p className="text-xs text-muted-foreground mt-0.5 flex items-center justify-between gap-4">
              {meta?.ext} · {meta?.size}
              <span className="flex items-center gap-1 text-xs">
                <StatusIndicator status={status} />
                {timeLeft && `${timeLeft}`}
              </span>
            </p>
          </div>

          <button
            onClick={() => onRemove?.(id)}
            className="w-8 h-8 rounded-full border border-border/60 bg-muted/20 flex items-center justify-center text-muted-foreground hover:text-foreground hover:border-border transition-colors shrink-0"
          >
            <IconX size={14} strokeWidth={2.5} />
          </button>
        </div>

        {status !== "idle" && (
          <ProgressBar progress={progress} status={status} />
        )}
        {hasError && <p className="text-[11px] text-red-500">{error}</p>}
      </motion.div>
    );
  }
  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
      transition={{ duration: 0.2 }}
      className="flex flex-col  rounded-xl border border-border/60 bg-muted/20 px-4 py-3.5 shadow-sm relative aspect-square justify-between"
    >
      <div className=" absolute inset-x-0 top-0 p-2 flex items-center justify-between">
        <span className="flex items-center gap-1 text-xs">
          <Popover>
            <PopoverTrigger>
              <StatusIndicator status={status} />
            </PopoverTrigger>
            <PopoverContent className="max-w-40" dir="bottom" side="top">
              {hasError && (
                <p className="text-[11px] dark:text-red-500 text-red-600">
                  {error}
                </p>
              )}
            </PopoverContent>
          </Popover>
          {timeLeft && `${timeLeft}`}
        </span>
        <button
          onClick={() => onRemove?.(id)}
          className="w-6 h-6 rounded-md border border-border/60 bg-muted/20 flex items-center justify-center text-muted-foreground hover:text-foreground hover:border-border transition-colors shrink-0"
        >
          <IconX size={12} strokeWidth={2.5} />
        </button>
      </div>
      <div className="flex flex-col items-center flex-1  justify-end pt-4 pb-2">
        <div
          className={cn(
            "w-11 h-11 rounded-lg bg-primary/10 flex items-center justify-center ",
            status === "error" && "bg-red-500/10",
          )}
        >
          {status === "error" ? (
            onRetry && (
              <button
                onClick={() => onRetry(id)}
                type="button"
                className="text-[10px] text-red-500 hover:text-red-400 flex items-center gap-1 text-xl cursor-pointer"
              >
                <IconRefresh size={24} strokeWidth={2} />
              </button>
            )
          ) : (
            <FileTypeIcon file={file} size={22} />
          )}
        </div>
      </div>

      <div className=" space-y-2">
        <div className="">
          <p className="text-xs font-medium line-clamp-1 text-foreground">
            {name}
          </p>
          <div className="text-xs text-muted-foreground mt-0.5">
            {meta?.ext} · {meta?.size}
          </div>
        </div>

        {status !== "idle" && (
          <ProgressBar progress={progress} status={status} />
        )}
      </div>
    </motion.div>
  );
}

import { useState } from "react";
import { useFileUpload } from "./file-upload-context";
import { FileUploadItem } from "./file-upload-item";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  IconClearAll,
  IconLayoutGrid,
  IconList,
  IconUpload,
} from "@tabler/icons-react";
import { AnimatePresence } from "motion/react";

export function FileUploadList() {
  const {
    config,
    files,
    removeFile,
    uploadAll,
    removeAll,
    cancelFile,
    retryFile,
    isUploading,
  } = useFileUpload();
  const { auto } = config;
  const [isList, setIsList] = useState(false);

  if (files.length === 0) return null;

  const pendingCount = files.filter((f) => f.status === "idle").length;
  const doneCount = files.filter((f) => f.status === "done").length;

  return (
    <section className="@container/upload-list not-visited:flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <span className="text-xs text-muted-foreground">
          {files.length} file{files.length !== 1 ? "s" : ""}
          {doneCount > 0 && ` · ${doneCount} uploaded`}
        </span>

        <div className="flex items-center gap-1.5">
          {files.length > 0 && (
            <Button onClick={removeAll} variant={"destructive"} size={"sm"}>
              <IconClearAll />
              Clear all
            </Button>
          )}
          <div className="flex items-center rounded-sm border border-border/60 overflow-hidden">
            <button
              onClick={() => setIsList(false)}
              className={cn(
                "flex items-center justify-center w-7 h-7 transition-colors",
                !isList
                  ? "bg-muted text-foreground"
                  : "text-muted-foreground hover:text-foreground hover:bg-muted/50",
              )}
              title="Grid view"
            >
              <IconLayoutGrid size={14} strokeWidth={1.8} />
            </button>
            <button
              onClick={() => setIsList(true)}
              className={cn(
                "flex items-center justify-center w-7 h-7 transition-colors",
                isList
                  ? "bg-muted text-foreground"
                  : "text-muted-foreground hover:text-foreground hover:bg-muted/50",
              )}
              title="List view"
            >
              <IconList size={14} strokeWidth={1.8} />
            </button>
          </div>
        </div>
      </div>

      <div
        className={cn(
          isList
            ? "flex flex-col gap-2"
            : "grid grid-cols-2 gap-2 @md/upload-list:grid-cols-3 @lg/upload-list:grid-cols-4 @2xl/upload-list:grid-cols-5 @4xl/upload-list:grid-cols-6",
        )}
      >
        <AnimatePresence>
          {files.map((file) => (
            <FileUploadItem
              key={file.id}
              {...file}
              isList={isList}
              onRemove={removeFile}
              onCancel={cancelFile}
              onRetry={retryFile}
            />
          ))}
        </AnimatePresence>
      </div>

      {pendingCount > 0 && !auto && (
        <div className="flex justify-end">
          <Button onClick={uploadAll} disabled={isUploading}>
            <IconUpload size={14} strokeWidth={2} />
            {isUploading
              ? "Uploading..."
              : `Upload ${pendingCount} file${pendingCount !== 1 ? "s" : ""}`}
          </Button>
        </div>
      )}
    </section>
  );
}

import React from "react";
import {
  FileUploadProvider,
  type FileUploadProviderProps,
} from "./file-upload-context";
import { FileUploadDropzone } from "./file-upload-dropzone";
import { FileUploadList } from "./file-upload-list";

interface FileUploadRootProps extends FileUploadProviderProps {
  /** Render custom children instead of the default dropzone + list layout */
  children?: React.ReactNode;
}

/**
 * FileUploadRoot — single import that composes the full system.
 *
 * Uses default layout (dropzone + list) unless you pass children.
 *
 * @example — default layout
 * <FileUploadRoot
 *   config={{ maxSize: 5 * 1024 * 1024, accept: { "image/*": [] } }}
 *   onUpload={async (file, onProgress) => {
 *     const url = await uploadToS3(file, onProgress);
 *     return { url };
 *   }}
 * />
 *
 * @example — custom layout
 * <FileUploadRoot onUpload={...}>
 *   <MyCustomDropzone />
 *   <MyCustomList />
 * </FileUploadRoot>
 */
export function FileUploadRoot({
  children,
  ...providerProps
}: FileUploadRootProps) {
